const libFableServiceProviderBase = require('fable-serviceproviderbase');

/**
 * PictProvider-Flow-SVGHelpers
 *
 * Shared SVG element creation utility used by all flow components
 * that need to create SVG namespace elements (nodes, connections, tethers).
 */
class PictProviderFlowSVGHelpers extends libFableServiceProviderBase
{
	constructor(pFable, pOptions, pServiceHash)
	{
		super(pFable, pOptions, pServiceHash);

		this.serviceType = 'PictProviderFlowSVGHelpers';
	}

	/**
	 * Create an SVG namespace element.
	 *
	 * @param {string} pTagName - The SVG element tag name (e.g., 'path', 'circle', 'g', 'rect', 'text')
	 * @returns {SVGElement}
	 */
	createSVGElement(pTagName)
	{
		return document.createElementNS('http://www.w3.org/2000/svg', pTagName);
	}

	/**
	 * Create a group whose contents keep a CONSTANT ON-SCREEN size no matter the viewport zoom.
	 *
	 * Everything inside the viewport is drawn in board units and scaled by the viewport transform, which
	 * is right for content and wrong for the grab handles you manipulate content WITH: a 6-unit rotate grip
	 * is 6 screen pixels at 1:1 and well under one pixel on a board zoomed out to see something very wide,
	 * at which point the handle exists but cannot be hit. Interaction chrome should hold still in the one
	 * coordinate system the mouse lives in.
	 *
	 * So the handle geometry goes inside a group anchored at its attach point and counter-scaled by 1/zoom,
	 * with the shapes drawn around the group's own origin. The anchor is kept on the element so
	 * ViewportManager.updateZoomInvariantChrome can rewrite the scale on every pan/zoom without a re-render.
	 * Counter-scaling also rescues the stroke widths, which shrink the same way.
	 *
	 * @param {number} pAnchorX - X of the attach point, in board units.
	 * @param {number} pAnchorY - Y of the attach point, in board units.
	 * @param {number} pZoom - The current viewport zoom.
	 * @returns {SVGGElement}
	 */
	createZoomInvariantGroup(pAnchorX, pAnchorY, pZoom)
	{
		let tmpGroup = this.createSVGElement('g');
		let tmpX = Number(pAnchorX) || 0;
		let tmpY = Number(pAnchorY) || 0;
		tmpGroup.setAttribute('class', 'pict-flow-zoom-invariant');
		tmpGroup.setAttribute('data-zoom-anchor-x', String(tmpX));
		tmpGroup.setAttribute('data-zoom-anchor-y', String(tmpY));
		tmpGroup.setAttribute('transform', this.zoomInvariantTransform(tmpX, tmpY, pZoom));
		return tmpGroup;
	}

	/**
	 * The transform a zoom-invariant group carries: move to the anchor, then undo the viewport scale.
	 * Shared by creation and by the per-zoom refresh so the two can never drift apart.
	 *
	 * @param {number} pAnchorX
	 * @param {number} pAnchorY
	 * @param {number} pZoom
	 * @returns {string}
	 */
	zoomInvariantTransform(pAnchorX, pAnchorY, pZoom)
	{
		let tmpZoom = Number(pZoom);
		// A zero, negative or missing zoom would blow up the reciprocal; fall back to 1 (no counter-scale).
		let tmpInverse = (isFinite(tmpZoom) && tmpZoom > 0) ? (1 / tmpZoom) : 1;
		return 'translate(' + (Number(pAnchorX) || 0) + ', ' + (Number(pAnchorY) || 0) + ') scale(' + tmpInverse + ')';
	}
}

module.exports = PictProviderFlowSVGHelpers;
